using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace tounsiYoyo.Model
{
    public class Special
    {
        public string ID { get; set; }
        public string Name { get; set; }
        public string Picture { get; set; } = "data:image/jpeg;base64,";
        public float Price { get; set; }

        public Special(string ID, string Name, float Price)
        {
            this.ID = ID;
            this.Name = Name;
            this.Price = Price;
            Picture = Picture;
        }

    }
}
